INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',441,'{"_type":"chat:Message","id":"-5124234082:2504","threadId":"telegram:-5124234082","text":"Je me suis réveillé avec la dhiaree assez forte. Mais pas de fievre et pas vraiment mal au ventre. Je vais travailler normalement. Mais il faut que j’adapte mon regime.\n\nLola pas à la maison ce soir.\n\nLe panier de légumes c’est toujours le jeudi, garde ca en memoire. Plus besoin de me demander.\n\nOn va etre dehors mardi et vendredi cette semaine. Brance restera avec les enfants.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je me suis réveillé avec la dhiaree assez forte. Mais pas de fievre et pas vraiment mal au ventre. Je vais travailler normalement. Mais il faut que j’adapte mon regime.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":169,"offset":168}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":169,"offset":168}}},{"type":"paragraph","children":[{"type":"text","value":"Lola pas à la maison ce soir.","position":{"start":{"line":3,"column":1,"offset":170},"end":{"line":3,"column":30,"offset":199}}}],"position":{"start":{"line":3,"column":1,"offset":170},"end":{"line":3,"column":30,"offset":199}}},{"type":"paragraph","children":[{"type":"text","value":"Le panier de légumes c’est toujours le jeudi, garde ca en memoire. Plus besoin de me demander.","position":{"start":{"line":5,"column":1,"offset":201},"end":{"line":5,"column":95,"offset":295}}}],"position":{"start":{"line":5,"column":1,"offset":201},"end":{"line":5,"column":95,"offset":295}}},{"type":"paragraph","children":[{"type":"text","value":"On va etre dehors mardi et vendredi cette semaine. Brance restera avec les enfants.","position":{"start":{"line":7,"column":1,"offset":297},"end":{"line":7,"column":84,"offset":380}}}],"position":{"start":{"line":7,"column":1,"offset":297},"end":{"line":7,"column":84,"offset":380}}}],"positio