INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',195,'{"_type":"chat:Message","id":"8641420749:504","threadId":"telegram:8641420749","text":"Ok parfait.\nJe ne comprends pas pourquoi tu ne store pas les données historiques de la meme maniere pour avril - juin 2026 et avant avril ?\nTu devrais les storer de la maniere la plus efficient pour ensuite faire des query.  Let’s design the best data storage strategy before implementing.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ok parfait.\nJe ne comprends pas pourquoi tu ne store pas les données historiques de la meme maniere pour avril - juin 2026 et avant avril ?\nTu devrais les storer de la maniere la plus efficient pour ensuite faire des query.  Let’s design the best data storage strategy before implementing.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":150,"offset":289}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":150,"offset":289}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":150,"offset":289}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-06T20:16:56.000Z","edited":false},"attachments":[],"isMention":false}',1783973816324);
