INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',199,'{"_type":"chat:Message","id":"8641420749:514","threadId":"telegram:8641420749","text":"I think we should store expenses only in one SQL table, also small reimbursement etc. And real incomes like salary, food, irs, bonus, holiday etc in another table. But expenses table shouldn’t show incomes.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I think we should store expenses only in one SQL table, also small reimbursement etc. And real incomes like salary, food, irs, bonus, holiday etc in another table. But expenses table shouldn’t show incomes.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":207,"offset":206}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":207,"offset":206}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":207,"offset":206}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-06T21:25:11.000Z","edited":false},"attachments":[],"isMention":false}',1783977911312);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',200,'{"_type":"chat:Message","id":"8641420749:517","threadId":"telegram:8641420749","text":"Attention ! Ne migre pas d’income depuis la table d’expenses vers la table d’income. Pour populer la table d’income tu ne dois te référer que au JSON qui ont été à partir des incomes que je t’ai transmis par message chaque moi. \nEnsuite une fois que tu auras fait ca tu pourras cross check avec la table d’expense et voir si certains credits marqués comme income dans la table d’expenses sont redondant ou a garder.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Attention ! Ne migre pas d’income depuis la table d’expenses vers la table d’income. Pour populer la table d’income tu ne dois te référer que au JSON qui ont été à partir des incomes que je t’ai transmis par message chaque moi.\nEnsuite une fois que tu auras fait ca tu pourras cross check avec la table d’expense et voir si certains credits marqués comme income dans la table d’expenses sont redondant ou a garder.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":187,"offset":415}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":187,"offset":415}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":187,"offset":415}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-06T21:30:10.000Z","edited":false},"attachments":[],"isMention":false}',1783978209741);
