INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',202,'{"_type":"chat:Message","id":"8641420749:522","threadId":"telegram:8641420749","text":"Ok. Just un commentaire : les inter account transfers de plus de 1000€ sont certainement ma participation au compte commun chaque mois, qui est calculé en fonction du salaire de chacun et avec l’objectif de mettre 4500€ par mois sur le compte commucommunn chaque","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ok. Just un commentaire : les inter account transfers de plus de 1000€ sont certainement ma participation au compte commun chaque mois, qui est calculé en fonction du salaire de chacun et avec l’objectif de mettre 4500€ par mois sur le compte commucommunn chaque","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":263,"offset":262}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":263,"offset":262}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":263,"offset":262}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-06T21:34:00.000Z","edited":false},"attachments":[],"isMention":false}',1783978439823);
