INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',204,'{"_type":"chat:Message","id":"8641420749:527","threadId":"telegram:8641420749","text":"1 - extra de contribution oui\n2 - j’ai donné 300€ de cash a un ami qui avait besoin et il m’a remboursé en paypal\n3 - contribution mensuelle oui\n4 - contributions mensuelles","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"1 - extra de contribution oui\n2 - j’ai donné 300€ de cash a un ami qui avait besoin et il m’a remboursé en paypal\n3 - contribution mensuelle oui\n4 - contributions mensuelles","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":29,"offset":173}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":29,"offset":173}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":29,"offset":173}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-06T21:43:36.000Z","edited":false},"attachments":[],"isMention":false}',1783979016416);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',205,'{"_type":"chat:Message","id":"8641420749:529","threadId":"telegram:8641420749","text":"Does the income SQL table has all income data since jan 2025? If not, it should. You have it all somewhere","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Does the income SQL table has all income data since jan 2025? If not, it should. You have it all somewhere","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":107,"offset":106}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":107,"offset":106}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":107,"offset":106}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-06T21:44:42.000Z","edited":false},"attachments":[],"isMention":false}',1783979082881);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',206,'{"_type":"chat:Message","id":"8641420749:521","threadId":"telegram:8641420749","text":"One thing I haven’t shared yet. Since I started running longer distances and more often a few years ago, i felt some pain on my feet. Sur le bord du gros orteil et de l’hallux valgus. Comme un pincement de la peau le long d’une ligne qui me forme une longue ampoule en forme de ligne. Ça empire quand je cours souvent. J’ai utilisé des bandes de protections, de la vaseline, ca aide un peu. \nJ’ai donc fait un test d’evaluation de ma foulée. Voila le resultat ci-dessous. Je devrais normalement commencer le renfo/exercices pour résoudre ce probleme mais je ne l’ai pas fait par flemme et manque de motivation. Il faut qu’on l’introduise de maniere raliste :\n\n\nAvaliação Biomecânica\n\nNome: Clement De Coligny\n\nHistorial Desportivo: Ciclista; Corrida, como complemento (há 2/3 anos);\n\nDistância em Competição: Ultra Distâncias, em Ciclismo\n\nPróxima Competição: 800 Kms (Maio 2026);\n\nFrequência Semanal de Treino:\n- 3 a 4x Ciclismo;\n- 2x Corrida;\n- 2x Treino Funcional, em Casa;\n\nRitmo de Treino: 5:00/km (Easy)\n\nHistorial de Lesões:\n- Assintomáticas: -;\n- Sintomáticas: Síndrome Patelar, Bilateral; \n\nPalmilhas: Sim; \n\nMassagem Desportiva: Sim;\n\nObs.: Usa\n- Hoka Clifton 10; \n\n\nDrop para os Ténis:  Drop 10 a 12 mm ( 4 Dedos )\n\nCalçado Recomendado:\n\n- Amortecimento Intermédio (3 cms)\n- Manter\n\n\nRelatório da Avaliação\n\nMúsculos Sub-Ativos: Grande e Médio Glúteo, sobretudo à Esquerda; Core; Gémeos; Tibial Posterior; \n\nMúsculos Encurtados:  Iliopsoas, Isquios; Adutores; Tibial Anterior; \n\nDéfice de Mobilidade: Lombar e Coxo-Femoral; Tibiotársica;\n\nCadência da Corrida: 183 PPM (Recomendado: 170-180 PPM).\n\nObs: Corrida:\n* Défice de Força no Grande e Médio Glúteo, sobretudo à Esquerda;\n* Cadência Lenta, mas menos (159 vs 163);\n* Encurtamento Isquiotibiais e Adutores;\n* Core\n\n\nLista de Exercícios\n\nPlano A\n\nMobilidade e Fortalecimento da Coluna e Anca -\n\n- Striders ( 3 x 10 ) - [https://www.youtube.com/watch?v=JGXYJ6Pgvt4](https://www.youtube.com/watch?v=JGXYJ6Pgvt4)\n\n- Frog Pose - ( 2 x 40 Segundos ) - [https://www.youtube.com/watch?v=bxO4MK8YDWE](https://www.youtube.com/watch?v=bxO4MK8YDWE)\n\n- Eccentric Addutor - ( 3 x 8 ) - [https://www.youtube.com/watch?v=-CmZenY5E6s](https://www.youtube.com/watch?v=-CmZenY5E6s)\n\n\nFortalecimento do Core –\n\n- Lateral Plank - ( 2 x 50 Segundos para cada lado ) - [https://www.youtube.com/watch?v=2SkCISN9Xng](https://www.youtube.com/watch?v=2SkCISN9Xng)\n\n- Back Extension Unilateral – ( 2 x 20 ) - [https://www.youtube.com/watch?v=DDJtB8Zgyow](https://www.youtube.com/watch?v=DDJtB8Zgyow)\n\n- Bicycle Crunch - ( 3 x 20 ) - [https://www.youtube.com/watch?v=1we3bh9uhqY](https://www.youtube.com/watch?v=1we3bh9uhqY)\n\n- Reverse Crunch - ( 3 x 15 ) - [https://www.youtube.com/watch?v=XY8KzdDcMFg](https://www.youtube.com/watch?v=XY8KzdDcMFg)\n\n\nMobilidade e Fortalecimento do Pé  –\n\n- Foot Inversion ( 3 x 15 ) - inversion exercise banded\n\n- Calves Raise w/ Tennis Ball ( 3 x 12 ) - [https://www.youtube.com/shorts/g6ipirkuLEA](https://www.youtube.com/shorts/g6ipirkuLEA)\n\n\n\nPlano B\n\nFortalecimento Coxas e Glúteos –\n\n- Bulgarian Lunge – ( 3 x 10 ) - [https://www.youtube.com/watch?v=vgn7bSXkgkA](https://www.youtube.com/watch?v=vgn7bSXkgkA)\n\n- One Leg Deadlift - ( 3 x 10 ) - [https://www.youtube.com/watch?v=VnHvZtV8Gz0](https://www.youtube.com/watch?v=VnHvZtV8Gz0)\n\n- One Leg Squat - ( 3 x 10 ) - [https://www.youtube.com/watch?v=9_Ca2YRRdtE](https://www.youtube.com/watch?v=9_Ca2YRRdtE)\n\n- Banded Kneeling Abduction – ( 3 x 10 ) -  [https://www.youtube.com/watch?v=NdhXzfLD1yM](https://www.youtube.com/watch?v=NdhXzfLD1yM)\n\n- Kneeling Hamstrings Slide - ( 3 x 8 ) - [https://www.youtube.com/watch?v=sZS8Q4tTylU](https://www.youtube.com/watch?v=sZS8Q4tTylU)\n\n- Banded Psoas ( 3 x 12 ) - [https://www.youtube.com/shorts/C1JdMDGBL1s](https://www.youtube.com/shorts/C1JdMDGBL1s)\n\n\nPlano A e B\n\nAlongamentos/LMF – (30 segundos cada)\n\n- Gémeos - [https://www.youtube.com/watch?v=0xd5KRCQP-s](https://www.youtube.com/watch?v=0xd5KRCQP-s)\n\n- Isquiotibiais - [https://www.youtube.com/watch?v=me22JRV7pJc](https://www.youtube.com/watch?v=me22JRV7pJc)\n\n- Glúteos - [https://www.youtube.com/watch?v=eRCpceBhcm0](https://www.youtube.com/watch?v=eRCpceBhcm0)\n\n- Quadricípite - [https://www.youtube.com/watch?v=DxBDqHL5NlM](https://www.youtube.com/watch?v=DxBDqHL5NlM)\n\n*\n___________________________________________________________________________________\n*\nObservações/Recomendações:\n\n- Pode realizar os Exercícios nos dias de Treino Curto ou de Baixa Intensidade, antes ou depois, ou em dias em que não realiza corrida.\n\n- Deverá realizar cada Plano 1x por Semana.\n\n- Poderá ainda agendar Sessões de Acompanhamento Personalizado na nossa Clínica, com os nossos Fisiologistas do Exercício;\n\n- Massagens Desportivas: Recomendação – 1x/mês (Poderá agendar de 2ª Feira a Sábado, na nossa Clínica)\n\n- Palmilhas: Sem Recomendação;\n\n- Duração do Plano de Exercícios: 10 a 12 Semanas;","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"One thing I haven’t shared yet. Since I started running longer distances and more often a few years ago, i felt some pain on my feet. Sur le bord du gros orteil et de l’hallux valgus. Comme un pincement de la peau le long d’une ligne qui me forme une longue ampoule en forme de ligne. Ça empire quand je cours souvent. J’ai utilisé des bandes de protections, de la vaseline, ca aide un peu.\nJ’ai donc fait un test d’evaluation de ma foulée. Voila le resultat ci-dessous. Je devrais normalement commencer le renfo/exercices pour résoudre ce probleme mais je ne l’ai pas fait par flemme et manque de motivation. Il faut qu’on l’introduise de maniere raliste :","position":{"start":{"line":1,"column":1,