INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',458,'{"_type":"chat:Message","id":"-5124234082:2548","threadId":"telegram:-5124234082","text":"I like this recipe too:\n\n@SteeleGolem\nIn a bowl, combine:\n2 cups oats\n1 cup shredded coconut\n3/4 cup chopped almonds\n1/8 cup chia seeds\n3 years ago (edited)\nIn a saucepan, whisk and boil:\n1/3 cup coconut oil\n1/3 cup sweetener (Maple syrup, honey, blue agave nectar)\nYour choice of spices for flavor\nMeanwhile, preheat oven to 275F.\nPour the liquid over your dry ingredients and fold in.\nSpread evenly on a parchment paper lined baking sheet and bake for 45 minutes.\n\n\nI just followed it using 800g oats. How much oil/sweetener? I use honey and olive oil","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I like this recipe too:","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":24,"offset":23}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":24,"offset":23}}},{"type":"paragraph","children":[{"type":"text","value":"@SteeleGolem\nIn a bowl, combine:\n2 cups oats\n1 cup shredded coconut\n3/4 cup chopped almonds\n1/8 cup chia seeds\n3 years ago (edited)\nIn a saucepan, whisk and boil:\n1/3 cup coconut oil\n1/3 cup sweetener (Maple syrup, honey, blue agave nectar)\nYour choice of spices for flavor\nMeanwhile, preheat oven to 275F.\nPour the liquid over your dry ingredients and fold in.\nSpread evenly on a parchment paper lined baking sheet and bake for 45 minutes.","position":{"start":{"line":3,"column":1,"offset":25},"end":{"line":16,"column":79,"offset":465}}}],"position":{"start":{"line":3,"column":1,"offset":25},"end":{"line":16,"column":79,"offset":465}}},{"type":"paragraph","children":[{"type":"text","value":"I just followed it using 800g oats. How much oil/sweetener? I use honey and olive oil","position":{"start":{"line":19,"column":1,"offset":468},"end":{"line":19,"column":86,"offset":553}}}],"position":{"start":{"line":19,"column":1,"offset":468},"end":{"line":19,"column":86,"offset":553}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":19,"column":86,"offset":553}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-07T21:40:38.000Z","edited":false},"attachments":[],"isMention":false}',1784065238496);
